    "id": "softcap",
    "source": "pragma silverscript ^0.1.0;\n\n// Soft-cap jar: anyone funds. Owner claims early only if this UTXO >= goalSompi;\n// after deadline owner may close for any amount. NOT a crowdfund — tip/goal jar only. Contributors are NOT auto-refunded\n// (each UTXO is independent). For refundable all-or-nothing use aon_pledge.\ncontract SoftCapJar(byte[32] ownerPkh, int goalSompi, temporal deadline) {\n    entry claim(pubkey pk, sig s) {\n        require(blake2b(byte[](pk)) == ownerPkh);\n        require(checkSig(s, pk));\n        require(tx.inputs[this.activeInputIndex].value >= goalSompi);\n    }\n\n    entry close(pubkey pk, sig s) {\n        require(blake2b(byte[](pk)) == ownerPkh);\n        require(checkSig(s, pk));\n        require(tx.time >= deadline);\n    }\n}\n",
